package com.alsafa.native4.core;

import android.content.ContentValues;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import com.alsafa.native4.sync.SyncOperation;
import org.json.JSONObject;
import java.util.UUID;

/** Online-sale settlement: shipping responsibility, shipping collection, deposits and later collections. */
public final class OnlineSaleSettlementStore {
 private final CoreStore.DbProvider provider; private final String deviceId;
 public OnlineSaleSettlementStore(CoreStore.DbProvider provider,String deviceId){this.provider=provider;this.deviceId=deviceId;}
 public Result create(String saleId,double merchandiseTotal,String saleCurrency,double shippingAmount,String shippingCurrency,boolean buyerPaysShipping,double paidNow,String paymentCurrency,String paymentMethod)throws Exception{
  String sid=req(saleId,"الفاتورة"),sc=currency(saleCurrency),shc=currency(shippingCurrency),pc=currency(paymentCurrency),pm=req(paymentMethod,"طريقة الدفع");valid(merchandiseTotal,"قيمة المنتجات");valid(shippingAmount,"أجرة الشحن");valid(paidNow,"المبلغ المدفوع");
  if(!sc.equals(shc)||!sc.equals(pc))throw new IllegalArgumentException("الدفعة الحالية تتطلب نفس عملة الفاتورة؛ تحويل العملات يسجل كعملية صرف مستقلة");
  double customerShipping=buyerPaysShipping?shippingAmount:0,totalDue=merchandiseTotal+customerShipping;if(paidNow>totalDue)throw new IllegalArgumentException("الدفعة أكبر من إجمالي المطلوب");double remaining=totalDue-paidNow;long now=System.currentTimeMillis();String settlementId="online-"+UUID.randomUUID();SQLiteDatabase db=provider.db();db.beginTransaction();try{
   ContentValues v=new ContentValues();v.put("settlement_id",settlementId);v.put("sale_id",sid);v.put("merchandise_total",merchandiseTotal);v.put("currency",sc);v.put("shipping_amount",shippingAmount);v.put("shipping_currency",shc);v.put("shipping_payer",buyerPaysShipping?"BUYER":"SELLER");v.put("total_due",totalDue);v.put("paid_total",paidNow);v.put("remaining",remaining);v.put("created_at",now);v.put("updated_at",now);db.insertOrThrow("online_sale_settlements",null,v);
   if(paidNow>0)insertPayment(db,settlementId,paidNow,pc,pm,"INITIAL",now);
   JSONObject j=payload(settlementId,sid,merchandiseTotal,sc,shippingAmount,shc,buyerPaysShipping,totalDue,paidNow,remaining,now);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.SALE_UPDATE,sid,j.toString(),deviceId));db.setTransactionSuccessful();return new Result(settlementId,totalDue,paidNow,remaining,sc);
  }finally{db.endTransaction();}
 }
 public Result collect(String settlementId,double amount,String currency,String paymentMethod)throws Exception{String id=req(settlementId,"تسوية بيع الإنترنت"),cur=currency(currency),pm=req(paymentMethod,"طريقة الدفع");valid(amount,"مبلغ التحصيل");if(amount<=0)throw new IllegalArgumentException("مبلغ التحصيل يجب أن يكون أكبر من صفر");SQLiteDatabase db=provider.db();db.beginTransaction();try{String saleId,base;double due,paid;try(Cursor c=db.rawQuery("SELECT sale_id,currency,total_due,paid_total FROM online_sale_settlements WHERE settlement_id=?",new String[]{id})){if(!c.moveToFirst())throw new IllegalArgumentException("تسوية البيع غير موجودة");saleId=c.getString(0);base=c.getString(1);due=c.getDouble(2);paid=c.getDouble(3);}if(!base.equals(cur))throw new IllegalArgumentException("عملة التحصيل مختلفة عن عملة الفاتورة");if(paid+amount>due)throw new IllegalArgumentException("التحصيل أكبر من المبلغ المتبقي");double newPaid=paid+amount,remaining=due-newPaid;long now=System.currentTimeMillis();ContentValues v=new ContentValues();v.put("paid_total",newPaid);v.put("remaining",remaining);v.put("updated_at",now);db.update("online_sale_settlements",v,"settlement_id=?",new String[]{id});insertPayment(db,id,amount,cur,pm,"COLLECTION",now);JSONObject j=new JSONObject().put("settlementId",id).put("saleId",saleId).put("collectionAmount",amount).put("currency",cur).put("paymentMethod",pm).put("paidTotal",newPaid).put("remaining",remaining).put("collectedAt",now);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.SALE_UPDATE,saleId,j.toString(),deviceId));db.setTransactionSuccessful();return new Result(id,due,newPaid,remaining,cur);}finally{db.endTransaction();}}
 private static void insertPayment(SQLiteDatabase db,String settlementId,double amount,String currency,String method,String type,long now){ContentValues p=new ContentValues();p.put("payment_id","payment-"+UUID.randomUUID());p.put("settlement_id",settlementId);p.put("amount",amount);p.put("currency",currency);p.put("payment_method",method);p.put("payment_type",type);p.put("created_at",now);db.insertOrThrow("online_sale_payments",null,p);}
 private static JSONObject payload(String id,String sale,double merchandise,String currency,double shipping,String shippingCurrency,boolean buyer,double due,double paid,double remaining,long now)throws Exception{return new JSONObject().put("settlementId",id).put("saleId",sale).put("saleChannel","ONLINE").put("merchandiseTotal",merchandise).put("currency",currency).put("shippingAmount",shipping).put("shippingCurrency",shippingCurrency).put("shippingPayer",buyer?"BUYER":"SELLER").put("totalDue",due).put("paidTotal",paid).put("remaining",remaining).put("updatedAt",now);}
 private static void valid(double v,String label){if(!Double.isFinite(v)||v<0)throw new IllegalArgumentException(label+" غير صالح");}private static String req(String v,String l){String s=v==null?"":v.trim();if(s.isEmpty())throw new IllegalArgumentException(l+" مطلوب");return s;}private static String currency(String v){String x=v==null?"":v.trim().toUpperCase();return x.equals("TRY")||x.equals("SYP")?x:"USD";}
 public static final class Result{public final String settlementId,currency;public final double totalDue,paidTotal,remaining;Result(String id,double due,double paid,double remaining,String currency){this.settlementId=id;this.totalDue=due;this.paidTotal=paid;this.remaining=remaining;this.currency=currency;}}
}
